          { text: 'PREPARE MAX REVERSE & SPOILERS', desc: 'Ensure full spoilers immediately upon touchdown.' }
        ]
      };
    case 'spoilers':
      return {
        title: 'SPOILERS INOPERATIVE',
        items: [
