import { mergeProviderResult } from './lib/provider-state.js';

const ALARM_NAME = 'aut-refresh';
const NOTIFICATION_ALARM_NAME = 'aut-notification';

const STALE_MS = 10 * 60 * 1000;   // only force a silent-tab refresh if cached data is older than this

let nativeWakeInFlight = null;
const apiRefreshInFlight = createInFlightRegistry();

init();

function init() {
  bindMessageHandlers();
  bindAlarm();
  refreshToolbarBadge().catch(console.error);
}

function bindMessageHandlers() {
  onMessage(async (msg, sender) => {
    if (!msg || !msg.type) return null;

    if (msg.type === 'aut/refresh') {
      await refreshNow({ allowSilentTab: true, force: true });
      return { ok: true };
    }
    if (msg.type === 'aut/reschedule') {
      await reschedule();
      return { ok: true };
    }
    if (msg.type === 'aut/settings-updated') {
      const state = await loadState();
      await scheduleNotificationAlarm(state, new Date());
      await refreshToolbarBadge();
      return { ok: true };
    }
    if (msg.type === 'aut/profile-updated') {
      await reschedule();
      await refreshToolbarBadge();
      return { ok: true };
    }
    if (msg.type === 'aut/get-snapshot') {
      return await loadState();
    }
    if (msg.type === 'aut/open-analytics') {
      await openAnalyticsTabs(msg.provider);
      return { ok: true };
    }
    if (msg.type === 'aut/scraped') {
      // Live snapshot from analytics-scraper.js running on the analytics page.
      const validation = validateScrapedMessage(msg, sender, {
        runtimeId: extensionRuntimeId(),
        now: new Date(),
      });
      if (!validation.ok) return rejectBackgroundMessage(validation);
      await ingestProviderSnapshot(msg.parsed, { source: 'live' });
      return { ok: true };
    }
    if (msg.type === 'aut/claude-message-limit') {
      const validation = validateClaudeBridgeMessage(msg, sender, {
        runtimeId: extensionRuntimeId(),
        now: new Date(),
        field: { messageType: 'aut/claude-message-limit', payloadKey: 'messageLimit' },
      });
      if (!validation.ok) return rejectBackgroundMessage(validation);
      await ingestClaudeUsageWindows(msg.messageLimit, { source: 'stream' });
      return { ok: true };
    }
    if (msg.type === 'aut/claude-rate-limit-headers') {
      const validation = validateClaudeBridgeMessage(msg, sender, {
        runtimeId: extensionRuntimeId(),
        now: new Date(),
        field: { messageType: 'aut/claude-rate-limit-headers', payloadKey: 'rateLimit' },
      });
      if (!validation.ok) return rejectBackgroundMessage(validation);
      await ingestClaudeUsageWindows(msg.rateLimit, { source: 'headers' });
      return { ok: true };
    }
    if (msg.type === 'aut/reset-claude-org') {
      clearClaudeOrgCache();
      await refreshNow({ allowSilentTab: false, force: true });
      return { ok: true };
    }
    return null;
  });
}

async function bindAlarm() {
  const state = await loadState();
  const minutes = state?.settings?.refreshMinutes ?? 5;
  schedule({
    name: ALARM_NAME,
    minutes,
    onFire: () => refreshNow({ allowSilentTab: true }).catch(console.error),
  });
  await scheduleNotificationAlarm(state, new Date());
}

async function reschedule() {
  await cancelSchedule(ALARM_NAME);
  await bindAlarm();
}

async function refreshNow({ allowSilentTab = false, force = false } = {}) {
  const now = new Date();
  let state = (await loadState()) || defaultState();
  const apiCredentials = await Promise.all(API_PROVIDER_IDS.map((provider) => loadApiCredential(provider)));

  // 1) Best-effort direct fetch. If either side is SSR'd we get a free win.
  const [claude, codex] = await Promise.all([
    fetchClaude({ now }).catch((e) => ({ ok: false, provider: 'claude', error: String(e) })),
    fetchCodex({ now }).catch((e) =>  ({ ok: false, provider: 'codex',  error: String(e) })),
  ]);
  const apiSnapshots = await Promise.all(API_PROVIDER_IDS.map(async (provider, index) => {
    const credential = apiCredentials[index];
    if (!credential) return { provider, credential: null, snapshot: null, skipped: false };

    const decision = decideProviderRefresh(state.snapshot?.providers?.[provider], { now, force });
    if (!decision.refresh) {
      return { provider, credential, snapshot: null, skipped: true, decision };
    }

    const key = `${state.profileId || 'default'}:${provider}`;
    const identity = `${credential}\u0000${provider}\u0000${providerRefreshSettingsKey(provider, state.settings)}`;
    const snapshot = await apiRefreshInFlight.getOrCreate(key, identity, () => fetchProviderUsage(provider, {
      credential,
      settings: state.settings,
      now,
    }).catch(() => ({
      ok: false,
      provider,
      error: 'api-refresh-failed',
      errorCode: `${provider}.refresh.failed`,
    })));
    return { provider, credential, snapshot, skipped: false, decision };
  }));
  state = await mergeSnapshot(state, claude, {
    source: 'fetch', now, persist: false, publish: false, recordHistory: false,
  });
  state = await mergeSnapshot(state, codex, {
    source: 'fetch', now, persist: false, publish: false, recordHistory: false,
  });
  for (const entry of apiSnapshots) {
    if (!entry.credential) {
      state = {
        ...state,
        snapshot: {
          ...state.snapshot,
          providers: { ...(state.snapshot?.providers || {}), [entry.provider]: null },
        },
      };
      state.budget = forgetApiProvider(state.budget, entry.provider, now);
    } else if (!entry.skipped) {
      state = await mergeSnapshot(state, entry.snapshot, {
        source: 'api-key', now, persist: false, publish: false, recordHistory: false,
      });
    }
  }
  state = recordRefreshHistory(state, now);
  state.budget = updateBudgetLedger(state.budget, state.snapshot, { now }).ledger;

  // 2) For any provider that's still stale, optionally ask a silent tab to refresh.
  if (allowSilentTab && state.settings?.silentTabRefresh === true) {
    const needsClaude = needsSilentRefresh(state, 'claude', now);
    const needsCodex  = needsSilentRefresh(state, 'codex',  now);
    if (needsClaude) await silentTabRefresh('claude');
    if (needsCodex)  await silentTabRefresh('codex');
    // The content script in those tabs will message `aut/scraped` back —
    // we don't await it here. Notifications will evaluate on that ingest.
  }

  await fireNotifications(state, now, { persist: false, schedule: false });
  await commitState(state);
  await scheduleNotificationAlarm(state, now);
  return state;
}

function handleNativeWake() {
  if (nativeWakeInFlight) return nativeWakeInFlight;
  nativeWakeInFlight = refreshNow({ allowSilentTab: true })
    .catch((error) => console.error('[AUT] native scheduler refresh failed:', error))
    .finally(() => { nativeWakeInFlight = null; });
  return nativeWakeInFlight;
}

function needsSilentRefresh(state, provider, now) {
  const ps = state?.snapshot?.providers?.[provider];
  if (!ps || !ps.ok) return true;
  // Use per-provider freshness timestamp if available, else fall back to snapshot-level.
  const providerTs = ps.lastSuccessISO ? new Date(ps.lastSuccessISO).getTime() : 0;
  const snapshotTs = state.snapshot.fetchedAtISO ? new Date(state.snapshot.fetchedAtISO).getTime() : 0;
  const ts = providerTs || snapshotTs;
  return (now.getTime() - ts) > STALE_MS;
}

async function silentTabRefresh(provider) {
  const ns = (typeof chrome !== 'undefined' && chrome.tabs)
          || (typeof browser !== 'undefined' && browser.tabs);
  if (!ns || !ns.create) return;

  const url = provider === 'claude'
    ? 'https://claude.ai/settings/usage'
    : 'https://chatgpt.com/codex/cloud/settings/analytics#usage';

  let tab;
  try {
    tab = await invokeWebExtension(ns, 'create', [{ url, active: false }]);
  } catch (e) {
    console.warn('[AUT] silent tab open failed', provider, e);
    return;
  }

  // Auto-close after 20s — the content script's stable-snapshot push should
  // have fired well before then.
  setTimeout(() => {
    if (ns.remove && tab && tab.id != null) {
      invokeWebExtension(ns, 'remove', [tab.id]).catch(() => {});
    }
  }, 20_000);
}

async function ingestProviderSnapshot(parsed, { source, now = new Date() } = {}) {
  if (!parsed || !parsed.provider) return;
  let state = (await loadState()) || defaultState();
  state = await mergeSnapshot(state, parsed, {
    source, now, persist: false, publish: false, recordHistory: false,
  });
  state = recordRefreshHistory(state, now);
  await fireNotifications(state, now, { persist: false, schedule: false });
  await commitState(state);
  await scheduleNotificationAlarm(state, now);
}

async function ingestClaudeUsageWindows(messageLimit, { source = 'stream', now = new Date() } = {}) {
  const cacheTimer = extractClaudeCacheTimer(messageLimit, { now, source });
  const parsed = parseClaudeUsageApi({ message_limit: messageLimit }, { now });
  if (!parsed.ok) {
    let failedState = (await loadState()) || defaultState();
    if (cacheTimer) failedState = mergeCacheTimer(failedState, cacheTimer);
    if (parsed.provider) {
      failedState = await mergeSnapshot(failedState, parsed, {
        source, now, persist: false, publish: false, recordHistory: false,
      });
      failedState = recordRefreshHistory(failedState, now);
      await fireNotifications(failedState, now, { persist: false, schedule: false });
      await commitState(failedState);
      await scheduleNotificationAlarm(failedState, now);
    } else if (cacheTimer) {
      await commitState(failedState);
    }
    return;
  }

  let state = (await loadState()) || defaultState();
  const previous = state.snapshot?.providers?.claude;
  const merged = mergeProviderBuckets(previous, { ...parsed, source });
  state = mergeCacheTimer(state, cacheTimer);
  state = await mergeSnapshot(state, merged, {
    source, now, persist: false, publish: false, recordHistory: false,
  });
  state = recordRefreshHistory(state, now);
  await fireNotifications(state, now, { persist: false, schedule: false });
  await commitState(state);
  await scheduleNotificationAlarm(state, now);
}

async function mergeSnapshot(
  state,
  providerSnapshot,
  { source, now, persist = true, publish = true, recordHistory = true } = {},
) {
  if (!providerSnapshot || !providerSnapshot.provider) return state;
  const next = {
    ...state,
    snapshot: {
      ...(state.snapshot || { fetchedAtISO: null, providers: {} }),
      providers: { ...(state.snapshot?.providers || {}) },
    },
  };
  const providerKey = providerSnapshot.provider;

  const prev = next.snapshot.providers[providerKey];
  const nowISO = now.toISOString();

  if (!providerSnapshot.ok) {
    const retry = computeRetryBackoff(prev?.refreshBackoffLevel, now, {
      retryable: isRetryableProviderError(providerSnapshot),
      retryAfterMs: providerSnapshot.retryAfterMs,
    });
    next.snapshot.providers[providerKey] = {
      ...mergeProviderResult(prev, providerSnapshot, { source, now }),
      refreshBackoffLevel: retry.level,
      nextRetryISO: retry.nextRetryISO,
      refreshSkippedReason: retry.nextRetryISO ? 'backoff' : null,
    };
  } else {
    next.snapshot.providers[providerKey] = {
      ...mergeProviderResult(prev, providerSnapshot, { source, now }),
      refreshBackoffLevel: 0,
      nextRetryISO: null,
      refreshSkippedReason: null,
    };
  }

  next.snapshot.fetchedAtISO = nowISO;
  if (recordHistory) next.history = recordSnapshot(next.history || [], next.snapshot, {
    now,
    retentionDays: next.settings?.historyRetentionDays,
  });
  if (persist) await saveState(next);
  if (publish) await publishSnapshot(next);
  return next;
}

function recordRefreshHistory(state, now) {
  return {
    ...state,
    history: recordSnapshot(state.history || [], state.snapshot, {
      now,
      retentionDays: state.settings?.historyRetentionDays,
    }),
  };
}

async function commitState(state) {
  await saveState(state);
  await publishSnapshot(state);
}

async function publishSnapshot(state) {
  await updateToolbarBadge(state);
  // Forward to QuotaGlass desktop widget (no-op if NMH not installed).
  try {
    const version = chrome.runtime?.getManifest?.()?.version;
    if (!isIncognitoContext()) pushSnapshot(state, version);
  } catch (e) {
    // Bridge failures must never break the extension's own data path.
    console.info('[AUT] bridge push failed:', e?.message || e);
  }
}

async function refreshToolbarBadge() {
  await updateToolbarBadge(await loadState());
}

function mergeProviderBuckets(previous, next) {
  if (!previous?.ok) return next;
  const buckets = new Map();
  for (const bucket of previous.buckets || []) buckets.set(bucket.id, bucket);
  for (const bucket of next.buckets || []) buckets.set(bucket.id, bucket);
  return {
    ...previous,
    ...next,
    plan: next.plan || previous.plan || null,
    orgId: next.orgId || previous.orgId || null,
    buckets: [...buckets.values()],
  };
}

function providerRefreshSettingsKey(provider, settings = {}) {
  if (provider === 'github-copilot') {
    return `${settings.githubCopilotOrganization || ''}:${settings.githubCopilotUsername || ''}`;
  }
  if (provider === 'gemini') return String(settings.geminiProjectId || '');
  return '';
}

function extensionRuntimeId() {
  return (typeof chrome !== 'undefined' && chrome.runtime?.id)
    || (typeof browser !== 'undefined' && browser.runtime?.id)
    || null;
}

function rejectBackgroundMessage(validation) {
  console.warn('[AUT] rejected background message', validation.errorCode);
  return validation;
}

async function fireNotifications(state, now, { persist = true, schedule = true } = {}) {
  const toFire = evaluateRules({
    snapshot: state.snapshot,
    history:  state.history,
    settings: state.settings,
    budget: state.budget,
    firedRules: state.firedRules || {},
    notificationRetries: state.notificationRetries || {},
    now,
  });
  state.firedRules = state.firedRules || {};
  state.notificationRetries = state.notificationRetries || {};
  for (const n of toFire) {
    let ok = false;
    let browserErrorCode = null;
    try {
      ok = await notify({ id: n.fireKey, title: n.title, body: n.body, tone: n.tone });
    } catch {
      browserErrorCode = 'browser.notification-failed';
    }
    let webhook = { ok: false, skipped: true };
    if (state.settings?.notifications?.webhookEnabled === true) {
      webhook = await deliverWebhook({
        url: state.settings.notifications.webhookURL,
        // Event-level retry state supplies the backoff between refreshes.
        // Keep each pass to one request so the total budget stays bounded.
        maxAttempts: 1,
        payload: buildWebhookPayload(n, {
          includeDetails: state.settings.notifications.webhookIncludeDetails === true,
          now,
        }),
      });
      recordWebhookStatus(state, webhook, now);
    }
    if (ok || webhook.ok) {
      state.firedRules[n.fireKey] = now.getTime();
      delete state.notificationRetries[n.fireKey];
    } else {
      state.notificationRetries[n.fireKey] = nextNotificationRetry({
        notification: n,
        previous: state.notificationRetries[n.fireKey],
        errorCode: webhook.errorCode || browserErrorCode || 'browser.notification-unavailable',
        now,
      });
    }
  }
  state.firedRules = pruneFired(state.firedRules, now);
  state.notificationRetries = pruneNotificationRetries(state.notificationRetries, now);
  if (persist) await saveState(state);
  if (schedule) await scheduleNotificationAlarm(state, now);
}

function recordWebhookStatus(state, result, now) {
  const notifications = { ...(state.settings?.notifications || {}) };
  notifications.webhookLastAttemptISO = now.toISOString();
  notifications.webhookLastAttempts = Number(result.attempts) || 0;
  if (result.ok) {
    notifications.webhookLastSuccessISO = now.toISOString();
    notifications.webhookLastErrorCode = null;
  } else {
    notifications.webhookLastErrorCode = result.errorCode || 'webhook.delivery-failed';
  }
  state.settings = { ...(state.settings || {}), notifications };
}

async function scheduleNotificationAlarm(state, now) {
  const next = deriveNextNotificationAlarm({
    snapshot: state?.snapshot,
    settings: state?.settings || {},
    firedRules: state?.firedRules || {},
    notificationRetries: state?.notificationRetries || {},
    now,
  });
  if (!next) {
    await cancelSchedule(NOTIFICATION_ALARM_NAME);
    syncNativeScheduler(state, null);
    return;
  }
  await scheduleAt({
    name: NOTIFICATION_ALARM_NAME,
    when: next.at,
    onFire: async () => {
      const current = await loadState();
      await fireNotifications(current || defaultState(), new Date());
    },
  });
  syncNativeScheduler(state, next.atISO);
}

function syncNativeScheduler(state, notificationAtISO = null) {
  return configureNativeScheduler({
    enabled: state?.settings?.nativeSchedulerEnabled === true,
    refreshMinutes: state?.settings?.refreshMinutes,
    notificationAtISO,
    onWake: handleNativeWake,
  });
}

async function openAnalyticsTabs(which = 'both') {
  const ns = (typeof chrome !== 'undefined' && chrome.tabs)
          || (typeof browser !== 'undefined' && browser.tabs);
  if (!ns || !ns.create) return;
  const urls = [];
  if (which === 'both' || which === 'claude') urls.push('https://claude.ai/settings/usage');
  if (which === 'both' || which === 'codex')  urls.push('https://chatgpt.com/codex/cloud/settings/analytics#usage');
  for (const url of urls) {
    invokeWebExtension(ns, 'create', [{ url, active: true }]).catch((error) => console.warn(error));
  }
}

function pruneFired(firedRules, now) {
  const cutoff = now.getTime() - 14 * 24 * 60 * 60 * 1000;
  const out = {};
  for (const [k, ts] of Object.entries(firedRules || {})) {
    if (typeof ts === 'number' && ts < cutoff) continue;
    out[k] = ts;
  }
  return out;
}

function pruneNotificationRetries(retries, now) {
  const cutoff = now.getTime() - 14 * 24 * 60 * 60 * 1000;
  const out = {};
  for (const [key, retry] of Object.entries(retries || {})) {
    const lastAttempt = new Date(retry?.lastAttemptISO || 0).getTime();
    if (Number.isFinite(lastAttempt) && lastAttempt < cutoff) continue;
    out[key] = retry;
  }
  return out;
}

